// Revenue conversion hook: records paidEvent on checkout success
// Called after successful payment processing

const fs = require('fs');
const path = require('path');

const REVENUE_LOG = path.join(__dirname, '..', 'data', 'revenue_events.jsonl');

function recordPaidEvent(order) {
  const event = {
    type: 'paidEvent',
    timestamp: new Date().toISOString(),
    orderId: order.id,
    amount: order.total,
    currency: order.currency || 'USD',
    customerId: order.customerId,
    productId: order.productId
  };
  fs.appendFileSync(REVENUE_LOG, JSON.stringify(event) + '\n');
  console.log('[RevenueHook] recorded paidEvent:', event.orderId);
}

// Hook into checkout success (assumes global event emitter or callback)
// This module should be required and wired in checkout route
module.exports = { recordPaidEvent };

// Auto-wire if global checkoutSuccessEmitter exists
if (typeof global.checkoutSuccessEmitter !== 'undefined') {
  global.checkoutSuccessEmitter.on('success', recordPaidEvent);
}
